use std::fmt::Write;
use melior::{Context, ExecutionEngine};
use melior::dialect::DialectRegistry;
use melior::ir::Module;
use melior::ir::operation::OperationLike;
use melior::utility::{register_all_dialects, register_all_llvm_translations};
use crate::{expr::{Block, Closure, Expr, Intrinsic, Statement}, jit::{CompiledClosure, DynamicCompiledClosure}, operators::expression_type, types::{CompileType, TypeInfo}, value::Value};

pub struct Compiler<'ctx>{pub(crate) context:&'ctx Context}
impl<'ctx> Compiler<'ctx>{
 pub fn new(context:&'ctx Context)->Self{Self{context}}
 pub fn compile<Args,Ret>(&self,closure:&Closure)->Result<CompiledClosure<'ctx,Args,Ret>,String> where Args:CompileType,Ret:CompileType+'static{let(module,name)=self.build_module(closure,"compiled_closure",false)?;let engine=ExecutionEngine::new(&module,0,&[],false,false);Ok(CompiledClosure::new(engine,name))}
 pub fn compile_dynamic(&self,closure:&Closure)->Result<DynamicCompiledClosure<'ctx>,String>{let(module,name)=self.build_module(closure,"compiled_dynamic_closure",true)?;let engine=ExecutionEngine::new(&module,0,&[],false,false);Ok(DynamicCompiledClosure::new(engine,name,closure.arguments.clone(),closure.return_type.clone()))}
 fn build_module(&self,closure:&Closure,name:&str,dynamic:bool)->Result<(Module<'ctx>,String),String>{let registry=DialectRegistry::new();register_all_dialects(&registry);self.context.append_dialect_registry(&registry);self.context.load_all_available_dialects();register_all_llvm_translations(self.context);let ir=MlirBuilder::new(name,closure,dynamic).build()?;let module=Module::parse(self.context,&ir).ok_or_else(||format!("failed to parse generated MLIR:\n{}",ir))?;if !module.as_operation().verify(){return Err(format!("generated MLIR failed verification:\n{}",ir));}Ok((module,name.to_string()))}
}

#[derive(Clone)] enum RefKind{Value,Address}
#[derive(Clone)] struct Ref{name:String,ty:TypeInfo,kind:RefKind}
struct MlirBuilder<'a>{name:&'a str,closure:&'a Closure,dynamic:bool,text:String,next_value:usize,next_block:usize,current_terminated:bool,refs:Vec<Ref>,args:Vec<Ref>,local_count:usize}
impl<'a> MlirBuilder<'a>{
 fn new(name:&'a str,closure:&'a Closure,dynamic:bool)->Self{Self{name,closure,dynamic,text:String::new(),next_value:0,next_block:0,current_terminated:false,refs:Vec::new(),args:Vec::new(),local_count:0}}
 fn value(&mut self)->String{let s=format!("%v{}",self.next_value);self.next_value+=1;s}
 fn block(&mut self,prefix:&str)->String{let s=format!("^{}_{}",prefix,self.next_block);self.next_block+=1;s}
 fn ty(t:&TypeInfo)->String{match t{TypeInfo::F32=>"f32".into(),TypeInfo::F64=>"f64".into(),TypeInfo::I8|TypeInfo::U8=>"i8".into(),TypeInfo::I16|TypeInfo::U16=>"i16".into(),TypeInfo::I32|TypeInfo::U32=>"i32".into(),TypeInfo::I64|TypeInfo::U64|TypeInfo::Usize=>"i64".into(),TypeInfo::I128|TypeInfo::U128=>"i128".into(),TypeInfo::Bool=>"i1".into(),TypeInfo::Array{element,length}=>format!("!llvm.array<{} x {}>",length,Self::ty(element)),TypeInfo::Slice{..}=>"!llvm.struct<(ptr, i64)>".into(),TypeInfo::Struct{fields,..}=>format!("!llvm.struct<({})>",fields.iter().map(|f|Self::ty(&f.type_info)).collect::<Vec<_>>().join(", "))}}
 fn one(&mut self)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.mlir.constant(1 : i64) : i64\n",v));v}
 fn c_i64(&mut self,n:i64)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.mlir.constant({} : i64) : i64\n",v,n));v}
 fn c_bool(&mut self,b:bool)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.mlir.constant({} : i1) : i1\n",v,b));v}
 fn c_int(&mut self,n:&str,ty:&str)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.mlir.constant({} : {}) : {}\n",v,n,ty,ty));v}
 fn c_float(&mut self,n:&str,ty:&str)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.mlir.constant({} : {}) : {}\n",v,n,ty,ty));v}
 fn alloca(&mut self,t:&TypeInfo)->String{let n=self.one();let v=self.value();self.text.push_str(&format!("    {} = llvm.alloca {} x {} : (i64) -> !llvm.ptr\n",v,n,Self::ty(t)));v}
 fn load(&mut self,p:&str,t:&TypeInfo)->String{self.load_raw(p,&Self::ty(t))}
 fn load_raw(&mut self,p:&str,t:&str)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.load {} : !llvm.ptr -> {}\n",v,p,t));v}
 fn store(&mut self,v:&str,p:&str,t:&TypeInfo){self.text.push_str(&format!("    llvm.store {}, {} : {}, !llvm.ptr\n",v,p,Self::ty(t)));}
 fn gep_const(&mut self,p:&str,t:&TypeInfo,indices:&[usize])->String{let v=self.value();let idx=indices.iter().map(|i|i.to_string()).collect::<Vec<_>>().join(", ");self.text.push_str(&format!("    {} = llvm.getelementptr {}[{}] : (!llvm.ptr) -> !llvm.ptr, {}\n",v,p,idx,Self::ty(t)));v}
 fn gep_dynamic(&mut self,p:&str,t:&TypeInfo,idx:&str)->String{self.gep_raw(p,&Self::ty(t),idx)}
 fn gep_raw(&mut self,p:&str,elem_ty:&str,idx:&str)->String{let v=self.value();self.text.push_str(&format!("    {} = llvm.getelementptr {}[{}] : (!llvm.ptr, i64) -> !llvm.ptr, {}\n",v,p,idx,elem_ty));v}
 fn emit_branch(&mut self,target:&str){self.text.push_str(&format!("    llvm.br {}\n",target));self.current_terminated=true}
 fn emit_cond(&mut self,c:&str,t:&str,f:&str){self.text.push_str(&format!("    llvm.cond_br {}, {}, {}\n",c,t,f));self.current_terminated=true}
 fn label(&mut self,label:&str){self.text.push_str(&format!("  {}:\n",label));self.current_terminated=false}
 fn bounds(&mut self,index:&str,len:&str)->Result<(),String>{let cmp=self.value();self.text.push_str(&format!("    {} = llvm.icmp \"ult\", {}, {} : i64\n",cmp,index,len));let ok=self.block("bounds_ok");let trap=self.block("bounds_trap");self.emit_cond(&cmp,&ok,&trap);self.label(&trap);self.text.push_str("    llvm.intr.trap\n    llvm.unreachable\n");self.current_terminated=true;self.label(&ok);Ok(())}
 fn build(mut self)->Result<String,String>{let arg_struct=TypeInfo::Struct{name:"args".into(),fields:self.closure.arguments.iter().enumerate().map(|(i,t)|crate::types::FieldInfo{name:i.to_string(),type_info:t.clone()}).collect()};writeln!(self.text,"module {{").unwrap();writeln!(self.text,"  llvm.func @{}(%args: !llvm.ptr, %result: !llvm.ptr) {{",self.name).unwrap();self.label("entry");for(i,t)in self.closure.arguments.iter().enumerate(){let v=if self.dynamic{let idx=self.c_i64(i as i64);let p=self.gep_raw("%args","ptr",&idx);let ap=self.load_raw(&p,"!llvm.ptr");self.load(&ap,t)}else{let p=self.gep_const("%args",&arg_struct,&[0,i]);self.load(&p,t)};let r=Ref{name:v.clone(),ty:t.clone(),kind:RefKind::Value};self.args.push(r.clone());self.refs.push(r);}let result=self.lower_block(&self.closure.body,Some(&self.closure.return_type))?;if let Some(r)=result{self.store(&r.name,"%result",&r.ty);}if !self.current_terminated{self.text.push_str("    llvm.return\n");}writeln!(self.text,"  }}\n}}").unwrap();Ok(self.text)}
 fn address_of_expr(&mut self,e:&Expr)->Result<Ref,String>{match e{Expr::Argument(i)=>{let t=self.closure.arguments.get(*i).cloned().ok_or("argument index out of bounds")?;if self.dynamic{let idx=self.c_i64(*i as i64);let p=self.gep_raw("%args","ptr",&idx);Ok(Ref{name:self.load_raw(&p,"!llvm.ptr"),ty:t,kind:RefKind::Address})}else{let at=TypeInfo::Struct{name:"args".into(),fields:self.closure.arguments.iter().enumerate().map(|(i,t)|crate::types::FieldInfo{name:i.to_string(),type_info:t.clone()}).collect()};Ok(Ref{name:self.gep_const("%args",&at,&[0,*i]),ty:t,kind:RefKind::Address})}},Expr::Field{object,name}=>{let base=self.address_of_expr(object)?;let fields=match &base.ty{TypeInfo::Struct{fields,..}=>fields,_=>return Err("field access requires a struct".into())};let(i,f)=fields.iter().enumerate().find(|(_,f)|f.name==*name).ok_or_else(||format!("field `{}` not found",name))?;Ok(Ref{name:self.gep_const(&base.name,&base.ty,&[0,i]),ty:f.type_info.clone(),kind:RefKind::Address})},Expr::Index{sequence,index}=>self.index_address(sequence,index),_=>Err("expression is not addressable".into())}}
 fn lower_ref(&mut self,e:&Expr,expected:&TypeInfo)->Result<Ref,String>{if let Ok(a)=self.address_of_expr(e){let v=self.load(&a.name,&a.ty);return Ok(Ref{name:v,ty:a.ty,kind:RefKind::Value})}self.lower_expr(e,expected)}
 fn index_address(&mut self,sequence:&Expr,index:&Expr)->Result<Ref,String>{let base=self.address_of_expr(sequence)?;let idx=self.lower_expr(index,&TypeInfo::Usize)?.name;match &base.ty{TypeInfo::Array{element,length}=>{let len=self.c_i64(*length as i64);self.bounds(&idx,&len)?;Ok(Ref{name:self.gep_dynamic(&base.name,&base.ty,&idx),ty:(**element).clone(),kind:RefKind::Address})},TypeInfo::Slice{element}=>{let data_p=self.gep_const(&base.name,&base.ty,&[0,0]);let len_p=self.gep_const(&base.name,&base.ty,&[0,1]);let data=self.load_raw(&data_p,"!llvm.ptr");let len=self.load(&len_p,&TypeInfo::Usize);self.bounds(&idx,&len)?;Ok(Ref{name:self.gep_dynamic(&data,element,&idx),ty:(**element).clone(),kind:RefKind::Address})},_=>Err("indexing requires an indexable sequence".into())}}
 fn lower_expr(&mut self,e:&Expr,expected:&TypeInfo)->Result<Ref,String>{match e{Expr::Argument(i)=>self.args.get(*i).cloned().ok_or_else(||format!("argument index {} out of bounds",i)),Expr::Constant(v)=>self.constant(v),Expr::Cast{expr,source_type,target_type}=>{let a=self.lower_ref(expr,source_type)?;self.cast(a,target_type)},Expr::Index{sequence,index}=>{let a=self.index_address(sequence,index)?;Ok(Ref{name:self.load(&a.name,&a.ty),ty:a.ty,kind:RefKind::Value})},Expr::Len{sequence}=>{let a=self.address_of_expr(sequence)?;match a.ty{TypeInfo::Array{length,..}=>Ok(Ref{name:self.c_i64(length as i64),ty:TypeInfo::Usize,kind:RefKind::Value}),TypeInfo::Slice{..}=>{let p=self.gep_const(&a.name,&a.ty,&[0,1]);Ok(Ref{name:self.load(&p,&TypeInfo::Usize),ty:TypeInfo::Usize,kind:RefKind::Value})},_=>Err("len() requires a sequence".into())}},Expr::Field{object,name}=>{let a=self.address_of_expr(object)?;let fields=match &a.ty{TypeInfo::Struct{fields,..}=>fields,_=>return Err("field access requires struct".into())};let(i,f)=fields.iter().enumerate().find(|(_,f)|f.name==*name).ok_or_else(||format!("field `{}` not found",name))?;let p=self.gep_const(&a.name,&a.ty,&[0,i]);Ok(Ref{name:self.load(&p,&f.type_info),ty:f.type_info.clone(),kind:RefKind::Value})},Expr::Struct{type_info,fields}=>self.aggregate(type_info,fields),Expr::Tuple{elements}=>{let ty=expression_type(&self.closure.arguments,e)?;let fields=elements.iter().enumerate().map(|(i,e)|(i.to_string(),e.clone())).collect::<Vec<_>>();self.aggregate(&ty,&fields)},Expr::Intrinsic{intrinsic,arguments}=>self.intrinsic(*intrinsic,arguments),Expr::IfElse{condition,then_branch,else_branch}=>self.if_expr(condition,then_branch,else_branch,expected),Expr::Add{lhs,rhs}=>self.binary("add",lhs,rhs,expected),Expr::Sub{lhs,rhs}=>self.binary("sub",lhs,rhs,expected),Expr::Mul{lhs,rhs}=>self.binary("mul",lhs,rhs,expected),Expr::Div{lhs,rhs}=>self.binary("div",lhs,rhs,expected),Expr::Rem{lhs,rhs}=>self.binary("rem",lhs,rhs,expected),Expr::Eq{lhs,rhs}=>self.compare("eq",lhs,rhs),Expr::Ne{lhs,rhs}=>self.compare("ne",lhs,rhs),Expr::Lt{lhs,rhs}=>self.compare("lt",lhs,rhs),Expr::Le{lhs,rhs}=>self.compare("le",lhs,rhs),Expr::Gt{lhs,rhs}=>self.compare("gt",lhs,rhs),Expr::Ge{lhs,rhs}=>self.compare("ge",lhs,rhs),Expr::And{lhs,rhs}=>self.logical("and",lhs,rhs),Expr::Or{lhs,rhs}=>self.logical("or",lhs,rhs),Expr::BitAnd{lhs,rhs}=>self.binary("and",lhs,rhs,expected),Expr::BitOr{lhs,rhs}=>self.binary("or",lhs,rhs,expected),Expr::BitXor{lhs,rhs}=>self.binary("xor",lhs,rhs,expected),Expr::Shl{lhs,rhs}=>self.binary("shl",lhs,rhs,expected),Expr::Shr{lhs,rhs}=>self.binary(if expected.is_signed_integer(){"ashr"}else{"lshr"},lhs,rhs,expected),Expr::Not{operand}=>{let a=self.lower_expr(operand,&TypeInfo::Bool)?;let one=self.c_bool(true);let n=self.value();self.text.push_str(&format!("    {} = llvm.xor {}, {} : i1\n",n,a.name,one));Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})},Expr::Neg{operand}=>{let a=self.lower_expr(operand,expected)?;let n=self.value();if expected.is_float(){self.text.push_str(&format!("    {} = llvm.fneg {} : {}\n",n,a.name,Self::ty(expected)))}else{let z=self.c_int("0",&Self::ty(expected));self.text.push_str(&format!("    {} = llvm.sub {}, {} : {}\n",n,z,a.name,Self::ty(expected)))}Ok(Ref{name:n,ty:expected.clone(),kind:RefKind::Value})}}}
 fn aggregate(&mut self,ty:&TypeInfo,fields:&[(String,Expr)])->Result<Ref,String>{let mut r=self.value();self.text.push_str(&format!("    {} = llvm.mlir.undef : {}\n",r,Self::ty(ty)));match ty{TypeInfo::Struct{fields:expected,..}=>{for(i,(name,e))in fields.iter().enumerate(){let f=expected.iter().find(|f|f.name==*name).ok_or("invalid struct field")?;let a=self.lower_expr(e,&f.type_info)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.insertvalue {}, {}[{}] : {}\n",n,a.name,r,i,Self::ty(ty)));r=n;}},TypeInfo::Array{element,..}=>{for(i,(_,e))in fields.iter().enumerate(){let a=self.lower_expr(e,element)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.insertvalue {}, {}[{}] : {}\n",n,a.name,r,i,Self::ty(ty)));r=n;}},_=>return Err("invalid aggregate type".into())}Ok(Ref{name:r,ty:ty.clone(),kind:RefKind::Value})}
 fn constant(&mut self,v:&Value)->Result<Ref,String>{match v{Value::F32(x)=>Ok(Ref{name:self.c_float(&x.to_string(),"f32"),ty:TypeInfo::F32,kind:RefKind::Value}),Value::F64(x)=>Ok(Ref{name:self.c_float(&x.to_string(),"f64"),ty:TypeInfo::F64,kind:RefKind::Value}),Value::Bool(x)=>Ok(Ref{name:self.c_bool(*x),ty:TypeInfo::Bool,kind:RefKind::Value}),Value::I8(x)=>self.int_const(*x as i128,"i8",TypeInfo::I8),Value::I16(x)=>self.int_const(*x as i128,"i16",TypeInfo::I16),Value::I32(x)=>self.int_const(*x as i128,"i32",TypeInfo::I32),Value::I64(x)=>self.int_const(*x as i128,"i64",TypeInfo::I64),Value::I128(x)=>self.int_const(*x as i128,"i128",TypeInfo::I128),Value::U8(x)=>self.int_const(*x as i128,"i8",TypeInfo::U8),Value::U16(x)=>self.int_const(*x as i128,"i16",TypeInfo::U16),Value::U32(x)=>self.int_const(*x as i128,"i32",TypeInfo::U32),Value::U64(x)=>self.int_const(*x as i128,"i64",TypeInfo::U64),Value::U128(x)=>self.int_const(*x as i128,"i128",TypeInfo::U128),Value::Usize(x)=>self.int_const(*x as i128,"i64",TypeInfo::Usize),Value::Array(v)=>{let first=v.first().ok_or("empty array constants are not supported")?.clone();let et=expression_type(&self.closure.arguments,&Expr::Constant(first))?;let ty=TypeInfo::Array{element:Box::new(et),length:v.len()};let fields=v.iter().enumerate().map(|(i,x)|(i.to_string(),Expr::Constant(x.clone()))).collect::<Vec<_>>();self.aggregate(&ty,&fields)}}}
 fn int_const(&mut self,x:i128,ty:&str,ti:TypeInfo)->Result<Ref,String>{Ok(Ref{name:self.c_int(&x.to_string(),ty),ty:ti,kind:RefKind::Value})}
 fn binary(&mut self,op:&str,lhs:&Expr,rhs:&Expr,ty:&TypeInfo)->Result<Ref,String>{let a=self.lower_expr(lhs,ty)?;let b=self.lower_expr(rhs,ty)?;let n=self.value();let inst=if ty.is_float(){match op{"add"=>"fadd","sub"=>"fsub","mul"=>"fmul","div"=>"fdiv","rem"=>"frem",_=>return Err("invalid floating binary op".into())}}else{match op{"div"=>if ty.is_unsigned_integer(){"udiv"}else{"sdiv"},"rem"=>if ty.is_unsigned_integer(){"urem"}else{"srem"},x=>x}};self.text.push_str(&format!("    {} = llvm.{} {}, {} : {}\n",n,inst,a.name,b.name,Self::ty(ty)));Ok(Ref{name:n,ty:ty.clone(),kind:RefKind::Value})}
 fn compare(&mut self,op:&str,lhs:&Expr,rhs:&Expr)->Result<Ref,String>{let t=expression_type(&self.closure.arguments,lhs)?;let a=self.lower_expr(lhs,&t)?;let b=self.lower_expr(rhs,&t)?;let n=self.value();if t.is_float(){let p=match op{"eq"=>"oeq","ne"=>"one","lt"=>"olt","le"=>"ole","gt"=>"ogt","ge"=>"oge",_=>return Err("bad comparison".into())};self.text.push_str(&format!("    {} = llvm.fcmp \"{}\", {}, {} : {}\n",n,p,a.name,b.name,Self::ty(&t)))}else{let p=match op{"eq"=>"eq","ne"=>"ne","lt"=>if t.is_unsigned_integer(){"ult"}else{"slt"},"le"=>if t.is_unsigned_integer(){"ule"}else{"sle"},"gt"=>if t.is_unsigned_integer(){"ugt"}else{"sgt"},"ge"=>if t.is_unsigned_integer(){"uge"}else{"sge"},_=>return Err("bad comparison".into())};self.text.push_str(&format!("    {} = llvm.icmp \"{}\", {}, {} : {}\n",n,p,a.name,b.name,Self::ty(&t)))}Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})}
 fn logical(&mut self,op:&str,lhs:&Expr,rhs:&Expr)->Result<Ref,String>{let a=self.lower_expr(lhs,&TypeInfo::Bool)?;let b=self.lower_expr(rhs,&TypeInfo::Bool)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.{} {}, {} : i1\n",n,op,a.name,b.name));Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})}
 fn cast(&mut self,a:Ref,target:&TypeInfo)->Result<Ref,String>{if a.ty==*target{return Ok(a)}let n=self.value();let s=Self::ty(&a.ty);let t=Self::ty(target);let op=if a.ty.is_float()&&target.is_float(){if Self::bits(target)<Self::bits(&a.ty){"fptrunc"}else{"fpext"}}else if a.ty.is_float(){if target.is_unsigned_integer(){"fptoui"}else{"fptosi"}}else if target.is_float(){if a.ty.is_unsigned_integer(){"uitofp"}else{"sitofp"}}else if Self::bits(target)<Self::bits(&a.ty){"trunc"}else if a.ty.is_unsigned_integer(){"zext"}else{"sext"};self.text.push_str(&format!("    {} = llvm.{} {} : {} to {}\n",n,op,a.name,s,t));Ok(Ref{name:n,ty:target.clone(),kind:RefKind::Value})}
 fn bits(t:&TypeInfo)->u32{match t{TypeInfo::I8|TypeInfo::U8=>8,TypeInfo::I16|TypeInfo::U16=>16,TypeInfo::I32|TypeInfo::U32=>32,TypeInfo::I64|TypeInfo::U64|TypeInfo::Usize=>64,TypeInfo::I128|TypeInfo::U128=>128,TypeInfo::Bool=>1,TypeInfo::F32=>32,TypeInfo::F64=>64,_=>0}}
 fn intrinsic(&mut self,i:Intrinsic,args:&[Expr])->Result<Ref,String>{let t=expression_type(&self.closure.arguments,&args[0])?;let a=self.lower_expr(&args[0],&t)?;let n=self.value();match i{Intrinsic::Sqrt|Intrinsic::Abs|Intrinsic::Floor|Intrinsic::Ceil|Intrinsic::Round|Intrinsic::Sin|Intrinsic::Cos|Intrinsic::Tan|Intrinsic::Exp|Intrinsic::Log=>{let op=match i{Intrinsic::Sqrt=>"sqrt",Intrinsic::Abs=>"fabs",Intrinsic::Floor=>"floor",Intrinsic::Ceil=>"ceil",Intrinsic::Round=>"round",Intrinsic::Sin=>"sin",Intrinsic::Cos=>"cos",Intrinsic::Tan=>"tan",Intrinsic::Exp=>"exp",Intrinsic::Log=>"log",_=>unreachable!()};self.text.push_str(&format!("    {} = llvm.intr.{}({}) : ({}) -> {}\n",n,op,a.name,Self::ty(&t),Self::ty(&t)));},Intrinsic::Min|Intrinsic::Max=>{let b=self.lower_expr(&args[1],&t)?;let op=if matches!(i,Intrinsic::Min){"minnum"}else{"maxnum"};self.text.push_str(&format!("    {} = llvm.intr.{}({}, {}) : ({}, {}) -> {}\n",n,op,a.name,b.name,Self::ty(&t),Self::ty(&t),Self::ty(&t)));},Intrinsic::Pow=>{let b=self.lower_expr(&args[1],&t)?;self.text.push_str(&format!("    {} = llvm.intr.pow({}, {}) : ({}, {}) -> {}\n",n,a.name,b.name,Self::ty(&t),Self::ty(&t),Self::ty(&t)));}}Ok(Ref{name:n,ty:t,kind:RefKind::Value})}
 fn if_expr(&mut self,c:&Expr,t:&Expr,e:&Expr,ty:&TypeInfo)->Result<Ref,String>{let cond=self.lower_expr(c,&TypeInfo::Bool)?;let temp=self.alloca(ty);let tb=self.block("if_then");let eb=self.block("if_else");let mb=self.block("if_merge");self.emit_cond(&cond.name,&tb,&eb);self.label(&tb);let tv=self.lower_expr(t,ty)?;self.store(&tv.name,&temp,ty);if !self.current_terminated{self.emit_branch(&mb)}self.label(&eb);let ev=self.lower_expr(e,ty)?;self.store(&ev.name,&temp,ty);if !self.current_terminated{self.emit_branch(&mb)}self.label(&mb);Ok(Ref{name:self.load(&temp,ty),ty:ty.clone(),kind:RefKind::Value})}
 fn lower_block(&mut self,b:&Block,expected:Option<&TypeInfo>)->Result<Option<Ref>,String>{for s in &b.statements{self.statement(s)?}if let Some(e)=&b.result{Ok(Some(self.lower_expr(e,expected.ok_or("block result has no expected type")? )?))}else{if expected.is_some(){return Err("block has no result expression".into())}Ok(None)}}
 fn statement(&mut self,s:&Statement)->Result<(),String>{match s{Statement::Let{local,type_info,value,..}=>{if *local!=self.local_count{return Err(format!("invalid local index {}",local))}let p=self.alloca(type_info);let v=self.lower_expr(value,type_info)?;self.store(&v.name,&p,type_info);self.refs.push(Ref{name:p,ty:type_info.clone(),kind:RefKind::Address});self.local_count+=1},Statement::Assign{local,value}=>{let idx=self.closure.arguments.len()+*local;let r=self.refs.get(idx).cloned().ok_or("local index out of bounds")?;let v=self.lower_expr(value,&r.ty)?;self.store(&v.name,&r.name,&r.ty)},Statement::AssignIndex{sequence,index,value}=>{let p=self.index_address(sequence,index)?;let v=self.lower_expr(value,&p.ty)?;self.store(&v.name,&p.name,&p.ty)},Statement::While{condition,body}=>{let cb=self.block("while_cond");let bb=self.block("while_body");let xb=self.block("while_exit");self.emit_branch(&cb);self.label(&cb);let c=self.lower_expr(condition,&TypeInfo::Bool)?;self.emit_cond(&c.name,&bb,&xb);self.label(&bb);self.lower_block(body,None)?;if !self.current_terminated{self.emit_branch(&cb)}self.label(&xb)},Statement::For{local,type_info,start,end,inclusive,body}=>{let p=self.alloca(type_info);let s=self.lower_expr(start,type_info)?;self.store(&s.name,&p,type_info);let cb=self.block("for_cond");let bb=self.block("for_body");let ib=self.block("for_inc");let xb=self.block("for_exit");self.emit_branch(&cb);self.label(&cb);let cur=self.load(&p,type_info);let ev=self.lower_expr(end,type_info)?;let cmp=self.value();let pred=if type_info.is_float(){if *inclusive{"ole"}else{"olt"}}else if type_info.is_unsigned_integer(){if *inclusive{"ule"}else{"ult"}}else if *inclusive{"sle"}else{"slt"};let op=if type_info.is_float(){"fcmp"}else{"icmp"};self.text.push_str(&format!("    {} = llvm.{} \"{}\", {}, {} : {}\n",cmp,op,pred,cur,ev.name,Self::ty(type_info)));self.emit_cond(&cmp,&bb,&xb);self.label(&bb);self.refs.push(Ref{name:p.clone(),ty:type_info.clone(),kind:RefKind::Address});self.local_count+=1;self.lower_block(body,None)?;self.local_count-=1;self.refs.pop();if !self.current_terminated{self.emit_branch(&ib)}self.label(&ib);let cur=self.load(&p,type_info);let one=self.c_int("1",&Self::ty(type_info));let n=self.value();let op=if type_info.is_float(){"fadd"}else{"add"};self.text.push_str(&format!("    {} = llvm.{} {}, {} : {}\n",n,op,cur,one,Self::ty(type_info)));self.store(&n,&p,type_info);self.emit_branch(&cb);self.label(&xb)}}Ok(())}
}
